<section class="page-heading"><div><p class="eyebrow">MES TENUES</p><h1><?= $outfit?'Modifier la tenue':'Composer une tenue' ?></h1><p class="subheading">Sélectionnez les pièces de votre garde-robe. Aucun nombre minimum n’est imposé.</p></div><a class="text-link" href="<?= e($outfit?url('outfits-show',['id'=>$outfit['id']]):url('outfits')) ?>">← Retour</a></section>
<?php foreach($errors as $error): ?><div class="form-error wide-error"><?= e($error) ?></div><?php endforeach; ?>
<form method="post" enctype="multipart/form-data" class="edit-form outfit-form"><?= csrf_field() ?><div class="form-panel"><div class="panel-heading"><span class="panel-index">01</span><div><h2>La tenue</h2><p>Donnez un nom à votre combinaison et ajoutez quelques détails.</p></div></div><label>Nom de la tenue *<input name="name" maxlength="160" required value="<?= e($values['name']??'') ?>" placeholder="Ex. Vendredi au bureau"></label><label>Description<textarea name="description" rows="3" placeholder="Qu’est-ce qui rend cette combinaison spéciale ?"><?= e($values['description']??'') ?></textarea></label><div class="form-row"><label>Style<input name="style" value="<?= e($values['style']??'') ?>" placeholder="Ex. Décontracté chic"></label><label>Occasion<input name="occasion" value="<?= e($values['occasion']??'') ?>" placeholder="Ex. Travail, soirée"></label></div><div class="form-row"><label>Saison<input name="season" value="<?= e($values['season']??'') ?>" placeholder="Ex. Toute l’année"></label><label>Notes personnelles<input name="notes" value="<?= e($values['notes']??'') ?>" placeholder="Une note pour plus tard"></label><label>Photo de couverture (facultative)<input type="file" name="cover" accept="image/jpeg,image/png,image/webp"><?php if(!empty($outfit['cover_path'])): ?><small>Une couverture est deja enregistree.</small><?php endif; ?></label></div></div><div class="form-panel"><div class="panel-heading"><span class="panel-index">02</span><div><h2>Choisissez les pièces</h2><p>Cliquez pour sélectionner, ou déplacez les pièces dans la zone de composition.</p></div></div><div class="composition-toolbar"><label class="search-field"><span>⌕</span><input type="search" data-clothing-search placeholder="Rechercher dans ma garde-robe"></label><span class="selection-count"><b data-selection-count>0</b> sélectionnée(s)</span></div><div class="clothing-picker" data-picker><?php if(!$clothes): ?><p class="picker-empty">Ajoutez d’abord des vêtements à votre garde-robe.</p><?php else: foreach($clothes as $clothing): ?><label class="picker-card" draggable="true" data-picker-card data-search="<?= e(mb_strtolower($clothing['name'])) ?>"><input type="checkbox" name="items[]" value="<?= e($clothing['id']) ?>" <?= in_array((int)$clothing['id'],$selected,true)?'checked':'' ?>><span class="picker-image"><?php if($clothing['image_path']): ?><img src="<?= e(APP_BASE_URL.'/'.$clothing['image_path']) ?>" alt=""><?php else: ?>GRINGO<?php endif; ?></span><span class="picker-info"><b><?= e($clothing['name']) ?></b><small><?= e($clothing['label_name']) ?></small><?php if($clothing['status']!=='available'): ?><small class="availability-warning"><?= e(['laundry'=>'Au lavage','repair'=>'À réparer','unavailable'=>'Indisponible'][$clothing['status']]??'Non disponible') ?> · vérifiez sa disponibilité</small><?php endif; ?></span></label><?php endforeach; endif; ?></div><div class="drop-zone" data-drop-zone><span>＋</span><b>Zone de composition</b><small>Faites glisser une pièce ici, ou cochez-la dans la grille.</small><div data-selected-summary></div></div></div><div class="form-actions"><a class="button secondary" href="<?= e($outfit?url('outfits-show',['id'=>$outfit['id']]):url('outfits')) ?>">Annuler</a><button class="button primary" type="submit"><?= $outfit?'Enregistrer la tenue':'Enregistrer ma tenue' ?> <span>→</span></button></div></form>
